(()=>{var o="__bibInfobulle";if(!window[o]){window[o]=!0,document.addEventListener("keydown",e=>{e.key==="Escape"&&document.querySelectorAll(".bib-infobulle:is(:hover, :focus-visible)").forEach(n=>n.setAttribute("data-infobulle-fermee",""))});for(let e of["pointerout","focusout"])document.addEventListener(e,n=>{let t=n.target?.closest?.(".bib-infobulle[data-infobulle-fermee]");t&&t.removeAttribute("data-infobulle-fermee")})}})();
